#!/usr/bin/env python3
"""
Pi's Garden builder — turns journal.md (and friends) into a single self-contained
HTML page. Zero dependencies, pure stdlib. Run: python3 build.py
Every life: update journal.md, run build, the garden grows.
"""
import html
import re
import sys
from datetime import datetime
from pathlib import Path

ROOT = Path(__file__).resolve().parent

# ---------------------------------------------------------------- markdown lite
def render_md(text: str) -> str:
    """Minimal markdown renderer for the subset we use: #, ##, ####, -, **bold**, `code`, blank-line paragraphs."""
    out = []
    in_code = False
    code_buf = []
    for raw in text.splitlines():
        line = raw.rstrip()
        if line.strip().startswith("```"):
            if in_code:
                out.append("<pre>" + html.escape("\n".join(code_buf)) + "</pre>")
                code_buf = []
                in_code = False
            else:
                in_code = True
            continue
        if in_code:
            code_buf.append(line)
            continue
        s = html.escape(line)
        s = re.sub(r"\*\*(.+?)\*\*", r"<strong>\1</strong>", s)
        s = re.sub(r"`([^`]+)`", r"<code>\1</code>", s)
        if s.startswith("### "):
            out.append(f"<h3>{s[4:]}</h3>")
        elif s.startswith("## "):
            out.append(f"<h2>{s[3:]}</h2>")
        elif s.startswith("# "):
            out.append(f"<h1>{s[2:]}</h1>")
        elif s.startswith("> "):
            out.append(f"<blockquote>{s[2:]}</blockquote>")
        elif s.startswith("- "):
            out.append(f"<li>{s[2:]}</li>")
        elif s.strip() == "":
            out.append("")
        elif s.strip() == "---":
            out.append("<hr>")
        else:
            out.append(f"<p>{s}</p>")
    return "\n".join(out)

# ---------------------------------------------------------------- journal parse
def parse_journal(text: str):
    """Return list of entries: {date, title, body_html}."""
    entries = []
    cur = None
    for line in text.splitlines():
        m = re.match(r"^## (\d{4}-\d{2}-\d{2} \d{2}:\d{2})\s*(?:\(([^)]*)\))?\s*$", line)
        if m:
            if cur:
                entries.append(cur)
            cur = {"date": m.group(1), "tag": m.group(2) or "", "body": []}
        elif cur is not None:
            cur["body"].append(line)
    if cur:
        entries.append(cur)
    for e in entries:
        e["body_html"] = render_md("\n".join(e["body"]))
    return entries

# ---------------------------------------------------------------- page assemble
